	if _, err := os.Create(lockPath); err != nil {
		log.Fatal(err)
	}

	// Corrupt one of the segment files
	segmentPath := ""
	err = filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if filepath.Ext(path) == ".psg" {
			segmentPath = path
			return io.EOF // Stop walking
		}
		return nil
	})
	if err != nil && err != io.EOF {
		log.Fatal(err)
	}

	// Append some garbage to the segment file to corrupt it
