		log.Fatal(err)
	}
	_, err = f.Write([]byte{0xFF, 0xFF, 0xFF, 0xFF})
	if err != nil {
		f.Close()
		log.Fatal(err)
	}
	f.Close()

	// Try to reopen the database - this should trigger recovery
	db, err = pogreb.Open(dir, nil)
	if err != nil {
		log.Fatal(err)
	}

	// Check that we can still read data
	for i := 0; i < 10; i++ {
		key := fmt.Sprintf("key%d", i)
